#!/usr/bin/env python3
"""Builds results_tables.md from raw/derived_rows.json (all 14 sequential requests). Standard library only."""
import json, statistics as st
rows = json.load(open('raw/derived_rows.json'))
out = ['# Results tables (generated by make_tables.py)', '', '`API s*` = POST sent until the first 1-second poll that saw the terminal state (1 s polling granularity + GET latency); it is NOT browser-visible latency.',
       '`non-inference overhead` = DB job duration minus llama.cpp total request time: a combined remainder (context and catalogue fetch, ranking, prompt construction, HTTP to llama.cpp, validation, persistence), not a phase breakdown.',
       '`prompt proc / total / cached` = prompt tokens actually evaluated / prompt tokens in the request / tokens reused from llama.cpp\'s prompt cache.',
       '`throttled periods` and `CPU s` are per-request deltas of the inference container\'s cgroup counters (window includes ~1-3 s of ssh overhead before and after the request).', '']
out.append('| run | case | req | eligible | pool | returned | queue s | job s | API s* | prompt proc / total / cached | gen tok | prompt s (tok/s) | gen s (tok/s) | llama total s | non-inference overhead s | outcome | throttled periods | CPU s |')
out.append('|' + '---|' * 18)
for r in rows:
    out.append('| %s | %s | %d | %d | %d | %d | %.2f | %.1f | %.1f | %d / %d / %d | %d | %.1f (%.1f) | %.2f (%.1f) | %.1f | %.2f | %s%s | %d/%d | %.1f |' % (
        r['tag'], r['case'], r['count'], r['elig'], r['pool'], r['ret'], r['qw'], r['job'], r['api'], r['proc'], r['tot'], r['cached'], r['gen'], r['pms'], r['ptps'], r['gms'], r['gtps'],
        r['lt'], r['ovh'], r['out'], '+fallback' if r['fb'] else '', r['thr'], r['per'], r['cpu']))
out += ['', 'M1-M7 = the seven requested runs (order: broad5, narrow5, broad5, narrow5, broad5, narrow5, broad20). S1-S7 = supplementary series with different filters, added because M3-M6 hit the prompt cache.', '',
        '| group | n | job s median (range) | API s* | prompt tokens processed | prompt tok/s | non-inference overhead s |', '|---|---|---|---|---|---|---|']
def line(label, sel):
    a = [r for r in rows if sel(r)]
    cells = ['%.1f (%.1f-%.1f)' % (st.median(v), min(v), max(v)) for v in ([r[k] for r in a] for k in ('job', 'api', 'proc', 'ptps', 'ovh'))]
    out.append('| %s | %d | %s |' % (label, len(a), ' | '.join(cells)))
cold = lambda r: r['proc'] > 100
line('broad, 5 results, cold prompt (M1, S1, S3, S5)', lambda r: r['count'] == 5 and r['pool'] == 30 and cold(r))
line('narrow, 5 results, cold prompt (M2, S2, S4, S6)', lambda r: r['count'] == 5 and r['pool'] < 30 and cold(r))
line('20 results (M7, S7; prefix partly cached)', lambda r: r['count'] == 20)
line('repeat of an identical prompt, cached (M3-M6)', lambda r: r['proc'] <= 1)
line('all 14 requests', lambda r: True)
open('results_tables.md', 'w').write('\n'.join(out) + '\n'); print('written')
